#!/usr/bin/env bash
set -euo pipefail

# Test: onboarding skill joiner fast-track
# Generated by /qa on 2026-04-16
# Covers: .claude/skills/onboarding/SKILL.md — verifies the joiner fast-track
# that prevents the "Edit blocked by onboarding-guard" UX trap for invitees.

SCRIPT_DIR="$(cd "$(dirname "$0")/../.." && pwd)"
SKILL="$SCRIPT_DIR/.claude/skills/onboarding/SKILL.md"

PASS=0
FAIL=0
pass() { PASS=$((PASS + 1)); echo "  ✓ $1"; return 0; }
fail() { FAIL=$((FAIL + 1)); echo "  ✗ $1"; [ -n "${2:-}" ] && echo "    $2"; return 0; }

echo "Testing: onboarding skill — joiner fast-track"
echo

# ── Skill file exists ─────────────────────────────────────────────

[ -f "$SKILL" ] && pass "onboarding SKILL.md exists" || fail "onboarding SKILL.md missing"

# ── Joiner fast-track section present in INVITE state ─────────────

grep -q "Joiner fast-track" "$SKILL" \
  && pass "INVITE state has 'Joiner fast-track' section" \
  || fail "no joiner fast-track — invitees will hit Edit-blocked trap"

grep -qE 'usage_type == "joiner_group".*run the Completion' "$SKILL" \
  && pass "fast-track gated on usage_type == joiner_group" \
  || fail "fast-track not properly gated by usage_type"

# ── Fast-track includes onboarding_complete=true write ────────────

# Find lines within ~15 lines of "Joiner fast-track" mentioning the flag flip
if awk '
  /Joiner fast-track/ { found=1; count=0 }
  found { count++ }
  found && count < 15 && /onboarding_complete/ { print "found"; exit }
' "$SKILL" | grep -q found; then
  pass "fast-track writes onboarding_complete=true (unblocks the hook)"
else
  fail "fast-track does not flip onboarding_complete — hook will still block"
fi

# ── FIRST_HANDOFF state scoped to founders ────────────────────────

grep -qE 'Creator.*usage_type.*founder_group.*signals session-end' "$SKILL" \
  && pass "FIRST_HANDOFF entry scoped to creators" \
  || fail "FIRST_HANDOFF may still trap joiners at session-end intent"

grep -qi "Joiners never reach this state" "$SKILL" \
  && pass "FIRST_HANDOFF explicitly notes joiners don't enter" \
  || fail "FIRST_HANDOFF doesn't document the joiner skip"

# ── Person file witness format documented ─────────────────────────

# Fast-track must upgrade invite stubs to the Onboarded: witness format,
# otherwise session-start auto-heal won't recognize joiners as onboarded.
grep -q "Onboarded:" "$SKILL" \
  && pass "person file witness (Onboarded:) referenced" \
  || fail "fast-track doesn't mention Onboarded: witness"

grep -qi "invite stub" "$SKILL" \
  && pass "fast-track handles invite stub upgrade case" \
  || fail "fast-track doesn't acknowledge invite stubs need upgrade"

# ── Rationale documented (so future maintainers don't revert) ─────

if grep -q "trap every first-time invitee" "$SKILL" \
   || grep -qi "hook blocks all Edit" "$SKILL"; then
  pass "rationale for fast-track documented"
else
  fail "no rationale — risk of future revert without understanding why"
fi

# ── Summary ───────────────────────────────────────────────────────

echo
echo "$PASS passed, $FAIL failed"
[ "$FAIL" -gt 0 ] && exit 1 || exit 0
